function summarizeArrayElements(arr) {
    const counts = {};

    for (const element of arr) {
        // If the element is already a key in counts, increment its value.
        // Otherwise, initialize its value to 1.
        counts[element] = (counts[element] || 0) + 1;
    }

    return counts;
}

