function createDelayedMessagePromise(message) {
  return new Promise((resolve, reject) => {
    if (message === "") {
      reject("Error: Message cannot be empty.");
    } else {
      setTimeout(() => {
        resolve(message);
      }, 100);
    }
  });
}

