class NetworkError extends Error {
    constructor(message) {
        super(message);
        this.name = "NetworkError";
    }
}

class AuthenticationError extends Error {
    constructor(message) {
        super(message);
        this.name = "AuthenticationError";
    }
}

class DataValidationError extends Error {
    constructor(message) {
        super(message);
        this.name = "DataValidationError";
    }
}

// The simulateFetchUserData function is provided in the problem description
// and will be available in the execution environment. You do not need to rewrite it.

function processUserDataRequest(userId) {
    try {
        const userData = simulateFetchUserData(userId);
        return { status: "success", data: userData };
    } catch (error) {
        if (error instanceof NetworkError) {
            return { status: "error", message: "Network issue: Could not reach the server." };
        } else if (error instanceof AuthenticationError) {
            return { status: "error", message: "Authentication failed: Invalid credentials." };
        } else if (error instanceof DataValidationError) {
            return { status: "error", message: "Data validation failed: User data is malformed." };
        } else {
            // Catch any other unexpected errors
            return { status: "error", message: `An unexpected error occurred: ${error.message}` };
        }
    }
}

