class Product {
    constructor(public id: string, public name: string, public price: number) {}
}

class Inventory {
    private products: Map<string, { product: Product; stock: number }>;

    constructor(initialProducts: Array<{ product: Product; stock: number }>) {
        this.products = new Map();
        for (const item of initialProducts) {
            this.products.set(item.product.id, { ...item });
        }
    }

    getProduct(productId: string): Product | undefined {
        return this.products.get(productId)?.product;
    }

    getStock(productId: string): number {
        return this.products.get(productId)?.stock || 0;
    }

    decreaseStock(productId: string, quantity: number): boolean {
        const item = this.products.get(productId);
        if (!item || item.stock < quantity) {
            return false;
        }
        item.stock -= quantity;
        return true;
    }

    increaseStock(productId: string, quantity: number): boolean {
        const item = this.products.get(productId);
        if (!item) {
            // For this problem, we assume increaseStock is only called for existing products
            // when returning items from the cart. If a product is not found in inventory,
            // it implies it was never added to the system initially.
            return false;
        }
        item.stock += quantity;
        return true;
    }
}

class ShoppingCart {
    private cartItems: Map<string, { product: Product; quantity: number }>;
    private inventory: Inventory;

    constructor(inventory: Inventory) {
        this.inventory = inventory;
        this.cartItems = new Map();
    }

    addItem(productId: string, quantity: number): boolean {
        if (quantity <= 0) return false;

        const product = this.inventory.getProduct(productId);
        if (!product) {
            return false;
        }

        if (this.inventory.decreaseStock(productId, quantity)) {
            const currentItem = this.cartItems.get(productId);
            if (currentItem) {
                currentItem.quantity += quantity;
            } else {
                this.cartItems.set(productId, { product, quantity });
            }
            return true;
        } else {
            return false;
        }
    }

    removeItem(productId: string, quantityToRemove?: number): boolean {
        const currentItem = this.cartItems.get(productId);
        if (!currentItem) {
            return false;
        }

        const actualQuantityToRemove = quantityToRemove === undefined || quantityToRemove >= currentItem.quantity
            ? currentItem.quantity
            : quantityToRemove;

        // Increase stock in inventory
        if (this.inventory.increaseStock(productId, actualQuantityToRemove)) {
            if (actualQuantityToRemove === currentItem.quantity) {
                this.cartItems.delete(productId);
            } else {
                currentItem.quantity -= actualQuantityToRemove;
            }
            return true;
        }
        // This case should ideally not be reached if inventory only contains valid products
        // and increaseStock is handled correctly for existing products.
        return false; 
    }

    getCartContents(): Array<{ productId: string; productName: string; price: number; quantity: number }> {
        const contents: Array<{ productId: string; productName: string; price: number; quantity: number }> = [];
        for (const [id, item] of this.cartItems.entries()) {
            contents.push({
                productId: item.product.id,
                productName: item.product.name,
                price: item.product.price,
                quantity: item.quantity
            });
        }
        contents.sort((a, b) => a.productId.localeCompare(b.productId)); // For consistent output
        return contents;
    }

    getTotalPrice(): number {
        let total = 0;
        for (const item of this.cartItems.values()) {
            total += item.product.price * item.quantity;
        }
        return total;
    }
}

// Wrapper function for test cases
function simulateShopping(
    productsData: Array<{id: string, name: string, price: number}>,
    initialInventoryData: {[productId: string]: number},
    operations: Array<[string, ...any[]]>
): (number | Array<{ productId: string; productName: string; price: number; quantity: number }> | boolean)[] {

    const productsMap = new Map<string, Product>();
    for (const p of productsData) {
        productsMap.set(p.id, new Product(p.id, p.name, p.price));
    }

    const inventoryItems = Object.entries(initialInventoryData).map(([id, stock]) => ({
        product: productsMap.get(id)!,
        stock: stock
    }));
    const inventory = new Inventory(inventoryItems);
    const cart = new ShoppingCart(inventory);

    const results: (number | Array<{ productId: string; productName: string; price: number; quantity: number }> | boolean)[] = [];

    for (const operation of operations) {
        const [methodName, ...args] = operation;

        let opResult: any; // Used to capture boolean return values
        switch (methodName) {
            case "addItem":
                opResult = cart.addItem(args[0], args[1]);
                if (opResult === false) { // Only push false for failed add operations
                    results.push(opResult);
                }
                break;
            case "removeItem":
                opResult = cart.removeItem(args[0], args[1]);
                if (opResult === false) { // Only push false for failed remove operations (e.g., product not in cart)
                    results.push(opResult);
                }
                break;
            case "getCartContents":
                results.push(cart.getCartContents());
                break;
            case "getTotalPrice":
                results.push(cart.getTotalPrice());
                break;
            default:
                console.warn(`Unknown operation: ${methodName}`);
        }
    }
    return results;
}

