    setCount(prevCount => prevCount + 1);
  };

  return (
    <div>
      {/* Display the current count */}
      <p>Count: {count}</p>
      {/* Button to increment the count on click */}
      <button onClick={incrementCount}>Increment</button>
    </div>
  );
}

