import React, { useState, useEffect } from 'react';

const UserRegistrationForm = () => {
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    password: '',
  });

  const [errors, setErrors] = useState({
    username: '',
    email: '',
    password: '',
  });

  const [isFormValid, setIsFormValid] = useState(false);
  const [registrationSuccess, setRegistrationSuccess] = useState(false);

  const validateField = (name, value) => {
    let error = '';
    switch (name) {
      case 'username':
        if (!value) {
          error = 'Username is required.';
        } else if (value.length < 3 || value.length > 15) {
          error = 'Username must be between 3 and 15 characters long.';
        } else if (!/^[a-zA-Z0-9]+$/.test(value)) {
          error = 'Username must contain only alphanumeric characters.';
        }
        break;
      case 'email':
        if (!value) {
          error = 'Email is required.';
        } else if (!/^[\w-.]+@([\w-]+\.)+[\w-]{2,4}$/.test(value)) {
          error = 'Please enter a valid email address.';
        }
        break;
      case 'password':
        if (!value) {
          error = 'Password is required.';
        } else if (value.length < 6) {
          error = 'Password must be at least 6 characters long.';
        } else if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*[0-9])/.test(value)) {
          error = 'Password must contain at least one uppercase letter, one lowercase letter, and one number.';
        }
        break;
      default:
        break;
    }
    return error;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prevData) => ({
      ...prevData,
      [name]: value,
    }));

    const error = validateField(name, value);
    setErrors((prevErrors) => ({
      ...prevErrors,
      [name]: error,
    }));
  };

  useEffect(() => {
    // Check overall form validity whenever formData or errors change
    const allFieldsValid = Object.keys(formData).every(
      (field) => formData[field] !== '' && errors[field] === ''
    );
    setIsFormValid(allFieldsValid);
  }, [formData, errors]);

  const handleSubmit = (e) => {
    e.preventDefault();

    // Re-validate all fields on submit to catch any un-validated on-blur fields
    let formIsValidOnSubmit = true;
    const newErrors = {};
    for (const fieldName in formData) {
      const error = validateField(fieldName, formData[fieldName]);
      newErrors[fieldName] = error;
      if (error) {
        formIsValidOnSubmit = false;
      }
    }
    setErrors(newErrors);

    if (formIsValidOnSubmit) {
      console.log('Registration Data:', formData);
      setRegistrationSuccess(true);
      // Optionally clear form fields after successful submission
      // setFormData({ username: '', email: '', password: '' });
      // setErrors({ username: '', email: '', password: '' });
    } else {
      setRegistrationSuccess(false);
      console.log('Form has errors. Cannot submit.');
    }
  };

  return (
    <div style={{ maxWidth: '400px', margin: '50px auto', padding: '20px', border: '1px solid #ccc', borderRadius: '8px' }}>
      <h2>Register</h2>
      {registrationSuccess && (
        <p style={{ color: 'green', fontWeight: 'bold' }}>Registration successful!</p>
      )}
      <form onSubmit={handleSubmit}>
        <div>
          <label htmlFor="username">Username:</label>
          <input
            type="text"
            id="username"
            name="username"
            value={formData.username}
            onChange={handleChange}
            aria-describedby="usernameError"
          />
          {errors.username && (
            <p id="usernameError" style={{ color: 'red', fontSize: '0.8em' }}>{errors.username}</p>
          )}
        </div>
        <div style={{ marginTop: '15px' }}>
          <label htmlFor="email">Email:</label>
          <input
            type="email"
            id="email"
            name="email"
            value={formData.email}
            onChange={handleChange}
            aria-describedby="emailError"
          />
          {errors.email && (
            <p id="emailError" style={{ color: 'red', fontSize: '0.8em' }}>{errors.email}</p>
          )}
        </div>
        <div style={{ marginTop: '15px' }}>
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            name="password"
            value={formData.password}
            onChange={handleChange}
            aria-describedby="passwordError"
          />
          {errors.password && (
            <p id="passwordError" style={{ color: 'red', fontSize: '0.8em' }}>{errors.password}</p>
          )}
        </div>
        <button type="submit" disabled={!isFormValid} style={{ marginTop: '20px', padding: '10px 20px', backgroundColor: isFormValid ? '#007bff' : '#cccccc', color: 'white', border: 'none', borderRadius: '5px', cursor: isFormValid ? 'pointer' : 'not-allowed' }}>
          Register
        </button>
      </form>
    </div>
  );
};

export default UserRegistrationForm;

