export default function PostDetail({ post, revalidateSecret }) {
    const router = useRouter();

    if (router.isFallback) {
        return <div>Loading...</div>;
    }

    if (!post) {
        return <div>Post not found.</div>;
    }

    const handleRevalidate = async () => {
        try {
            const response = await fetch(`/api/revalidate-post?id=${post.id}&secret=${revalidateSecret}`, {
                method: 'POST',
            });
            const data = await response.json();
            if (data.revalidated) {
                alert('Post revalidated successfully! Please refresh the page to see updates.');
            } else {
                alert(`Revalidation failed: ${data.message || 'Unknown error'}`);
            }
        } catch (error) {
            alert(`Error revalidating post: ${error.message}`);
        }
    };

    return (
        <div>
            <h1>{post.title}</h1>
            <p>{post.body}</p>
            <button onClick={handleRevalidate}>Revalidate This Post</button>
            <br />
            <Link href="/">
                <a>Back to home</a>
            </Link>
        </div>
    );
}

export async function getStaticPaths() {
    const posts = await getPosts();
    const paths = posts.map(post => ({
        params: { id: post.id },
    }));
    return { paths, fallback: 'blocking' }; // 'blocking' or true
}

export async function getStaticProps({ params }) {
    const post = await getPostById(params.id);

    if (!post) {
        return {
            notFound: true,
        };
    }

    // For demonstration, pass NEXT_PUBLIC_REVALIDATE_SECRET to client.
    // In production, consider a more secure approach.
    const revalidateSecret = process.env.NEXT_PUBLIC_REVALIDATE_SECRET;

    return {
        props: {
            post,
            revalidateSecret,
        },
        revalidate: 60, // Revalidate every 60 seconds
    };
}


// pages/api/revalidate-post.js
// This API route will be called to trigger on-demand revalidation.
// Make sure to set NEXT_REVALIDATE_SECRET and NEXT_PUBLIC_REVALIDATE_SECRET
// in your .env.local file (e.g., both to 'mysecrettoken').

export default async function handler(req, res) {
    // Check for secret to confirm this is a valid request
    if (req.method !== 'POST') {
        return res.status(405).json({ message: 'Method Not Allowed' });
    }

    const secret = req.query.secret;
    const postId = req.query.id;

    if (secret !== process.env.NEXT_REVALIDATE_SECRET || !postId) {
        console.log(`Revalidation attempt failed: Invalid token (${secret}) or missing ID (${postId})`);
        return res.status(401).json({ message: 'Invalid token or missing post ID' });
    }

    try {
        // Path to revalidate must match the path used in getStaticPaths, e.g., '/posts/1'
        await res.revalidate(`/posts/${postId}`);
        console.log(`Revalidated /posts/${postId} successfully.`);
        return res.json({ revalidated: true, now: Date.now() });
    } catch (err) {
        // If there was an error, Next.js will continue to serve the last successfully generated page
        console.error('Error revalidating:', err);
        return res.status(500).send('Error revalidating');
    }
}

