import { ref, reactive } from 'vue';

export default function setup() {
  const globalSettings = ref({
    theme: 'dark',
    language: 'en'
  });

  const userPreferences = reactive({
    notifications: { email: true, sms: false },
    profile: { displayName: 'VueFan' }
  });

  function setGlobalSettings(newSettings) {
    // When the entire object needs to be replaced, ref's .value is ideal.
    globalSettings.value = newSettings;
  }

  function updateGlobalSetting(key, value) {
    // Modifying properties of the object held by a ref is also reactive.
    if (globalSettings.value) {
      globalSettings.value[key] = value;
    }
  }

  // Helper function to update deeply nested properties
  function deepSet(obj, path, value) {
    const parts = path.split('.');
    let current = obj;
    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i];
      if (typeof current[part] !== 'object' || current[part] === null) {
        // Create an intermediate object if it doesn't exist
        current[part] = {};
      }
      current = current[part];
    }
    // Set the final property value
    current[parts[parts.length - 1]] = value;
  }

  function updateUserPreference(path, value) {
    // userPreferences is a reactive object, so direct manipulation and
    // adding new properties (even nested ones) are automatically reactive in Vue 3.
    deepSet(userPreferences, path, value);
  }

  function addPreferenceCategory(categoryName, initialValue) {
    // Adding a new top-level property to a reactive object is also reactive.
    if (!(categoryName in userPreferences)) {
      userPreferences[categoryName] = initialValue;
    }
  }

  return {
    globalSettings,
    userPreferences,
    setGlobalSettings,
    updateGlobalSetting,
    updateUserPreference,
    addPreferenceCategory
  };
}

