    { id: 101, title: "My first post", content: "Hello world!", authorId: 1 },
    { id: 102, title: "Another post by user 1", content: "This is by user 1.", authorId: 1 },
    { id: 103, title: "Admin's insights", content: "This post belongs to user 2 (admin).", authorId: 2 }
];
let nextPostId = 104;

// --- Mock Authentication Middleware --- 
// In a real application, this would decode a JWT or session token.
// For this problem, it simulates `req.user` based on custom headers.
const authenticationMiddleware = (req, res, next) => {
    const userId = parseInt(req.headers['x-user-id']);
    const userRole = req.headers['x-user-role'];

    if (isNaN(userId) || !userRole) {
        return res.status(401).json({ error: 'Unauthorized: Please provide authentication credentials.' });
    }

    req.user = { id: userId, role: userRole };
    next();
};

// --- Authorization Middleware --- 

// Middleware to check if the user is the author of the resource OR an admin
const authorizeOwnershipOrAdmin = (req, res, next) => {
    const postId = parseInt(req.params.id);
    const post = posts.find(p => p.id === postId);

    if (!post) {
        return res.status(404).json({ error: 'Post not found.' });
    }

    // Check if the user is the author OR an admin
    if (req.user.id === post.authorId || req.user.role === 'admin') {
        next();
    } else {
        return res.status(403).json({ error: 'Forbidden: You do not have permission to perform this action.' });
    }
};

// --- Routes --- 

// Apply authentication middleware to all routes that require it
app.use(authenticationMiddleware);

// 1. POST /posts: Create a new post (Any authenticated user)
app.post('/posts', (req, res) => {
    const { title, content } = req.body;
    if (!title || !content) {
        return res.status(400).json({ error: 'Title and content are required.' });
    }
    const newPost = { id: nextPostId++, title, content, authorId: req.user.id };
    posts.push(newPost);
    res.status(201).json(newPost);
});

// 2. GET /posts: Get all posts (Any authenticated user)
app.get('/posts', (req, res) => {
    res.status(200).json(posts);
});

// 3. GET /posts/:id: Get a specific post (Any authenticated user)
app.get('/posts/:id', (req, res) => {
    const postId = parseInt(req.params.id);
    const post = posts.find(p => p.id === postId);

    if (!post) {
        return res.status(404).json({ error: 'Post not found.' });
    }
    res.status(200).json(post);
});

// 4. PUT /posts/:id: Update an existing post (Author or Admin)
app.put('/posts/:id', authorizeOwnershipOrAdmin, (req, res) => {
    const postId = parseInt(req.params.id);
    const postIndex = posts.findIndex(p => p.id === postId);

    // authorizeOwnershipOrAdmin already handled 404, but double-check for robustness.
    if (postIndex === -1) {
        return res.status(404).json({ error: 'Post not found.' }); 
    }

    const { title, content } = req.body;
    if (!title || !content) {
        return res.status(400).json({ error: 'Title and content are required.' });
    }

    posts[postIndex] = { ...posts[postIndex], title, content };
    res.status(200).json(posts[postIndex]);
});

// 5. DELETE /posts/:id: Delete an existing post (Author or Admin)
app.delete('/posts/:id', authorizeOwnershipOrAdmin, (req, res) => {
    const postId = parseInt(req.params.id);
    const initialLength = posts.length;
    posts = posts.filter(p => p.id !== postId);

    // authorizeOwnershipOrAdmin already handled 404, but double-check for robustness.
    if (posts.length === initialLength) {
        return res.status(404).json({ error: 'Post not found.' });
    }
    res.status(204).send(); // No content for successful deletion
});

// Start the server
app.listen(PORT, () => {
    console.log(`Server running on http://localhost:${PORT}`);
});

module.exports = app; // Export for testing purposes
