import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[] findLocalPeaks(int[] arr) {
        if (arr == null || arr.length == 0) {
            return new int[0];
        }

        List<Integer> peaks = new ArrayList<>();

        // Case 1: Array with a single element
        if (arr.length == 1) {
            peaks.add(arr[0]);
            return new int[]{arr[0]};
        }

        // Case 2: Check the first element
        // It's a peak if it's strictly greater than its right neighbor
        if (arr[0] > arr[1]) {
            peaks.add(arr[0]);
        }

        // Case 3: Check middle elements
        // An element is a peak if it's strictly greater than both its left and right neighbors
        for (int i = 1; i < arr.length - 1; i++) {
            if (arr[i] > arr[i-1] && arr[i] > arr[i+1]) {
                peaks.add(arr[i]);
            }
        }

        // Case 4: Check the last element
        // It's a peak if it's strictly greater than its left neighbor
        if (arr[arr.length - 1] > arr[arr.length - 2]) {
            peaks.add(arr[arr.length - 1]);
        }

        // Convert the List of peaks to an int array
        int[] result = new int[peaks.size()];
        for (int i = 0; i < peaks.size(); i++) {
            result[i] = peaks.get(i);
        }

        return result;
    }
}

