public class EmployeeAnalyzer {

    /**
     * Calculates the average salary for employees within each department,
     * considering only employees whose age is greater than or equal to a specified minimum age.
     *
     * @param employees The list of all employees.
     * @param minAge The minimum age for an employee to be included in the calculation.
     * @return A Map where keys are department names and values are the average salaries of eligible employees.
     *         Departments with no eligible employees will not be present in the map.
     */
    public Map<String, Double> getAverageSalaryByDepartmentFilteredByAge(List<Employee> employees, int minAge) {
        return employees.stream()
                .filter(emp -> emp.getAge() >= minAge)
                .collect(Collectors.groupingBy(
                        Employee::getDepartment,
                        Collectors.averagingDouble(Employee::getSalary)
                ));
    }
}

import java.util.concurrent.ThreadLocalRandom;

// Warehouse class (Shared Resource)
class Warehouse {
    private final int capacity;
    private int currentStock;
    private final Object lock = new Object(); // Explicit lock object for synchronization

    public Warehouse(int capacity) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Warehouse capacity must be positive.");
        }
        this.capacity = capacity;
        this.currentStock = 0;
    }

    /**
     * Attempts to add a specified quantity of items to the warehouse.
     * This method must be thread-safe to prevent race conditions.
     * @param quantity The number of items to add.
     * @return true if items were successfully added, false otherwise (e.g., warehouse full).
     */
    public boolean addItem(int quantity) {
        if (quantity <= 0) {
            return false;
        }

        // Synchronize access to currentStock to ensure atomicity and visibility
        synchronized (lock) {
            if (currentStock + quantity <= capacity) {
                currentStock += quantity;
                return true;
            } else {
                return false;
            }
        }
    }

    /**
     * Gets the current stock level in the warehouse.
     * This method should also be thread-safe to ensure the returned value is consistent.
     * @return The current number of items in stock.
     */
    public int getCurrentStock() {
        synchronized (lock) { // Synchronize reads as well for strong consistency guarantee
            return currentStock;
        }
    }

    public int getCapacity() {
        return capacity;
    }
}

// Robot class (Worker Thread Logic)
class Robot implements Runnable {
    private final String robotId;
    private final Warehouse warehouse;
    private final int itemsToAttemptToAdd;

    public Robot(String robotId, Warehouse warehouse, int itemsToAttemptToAdd) {
        this.robotId = robotId;
        this.warehouse = warehouse;
        this.itemsToAttemptToAdd = itemsToAttemptToAdd;
    }

    @Override
    public void run() {
        Thread.currentThread().setName(robotId); // Set thread name for clearer debugging output

        for (int i = 0; i < itemsToAttemptToAdd; i++) {
            warehouse.addItem(1);
            // A small delay to encourage context switching and potential race conditions
            try {
                Thread.sleep(ThreadLocalRandom.current().nextInt(1, 10)); // Sleep between 1-9 ms
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
    }
}

// Main class to orchestrate the simulation, used by the testing framework
public class WarehouseManager {

    /**
     * Simulates multiple robots attempting to add items to a shared warehouse.
     * This method is designed to be called by the test framework.
     *
     * @param capacity The maximum capacity of the warehouse.
     * @param robotConfigs A 2D array where each inner array represents a robot:
     *                     `[itemsToAttemptToAdd]`
     *                     e.g., `[[7], [5]]` means Robot 1 tries to add 7, Robot 2 tries to add 5.
     * @return A string containing the final stock in the warehouse and its capacity.
     * @throws InterruptedException If any robot thread is interrupted.
     */
    public static String runSimulation(int capacity, int[][] robotConfigs) throws InterruptedException {
        Warehouse warehouse = new Warehouse(capacity);
        Thread[] robotThreads = new Thread[robotConfigs.length];

        for (int i = 0; i < robotConfigs.length; i++) {
            String robotId = "Robot-" + (i + 1);
            int itemsToAttempt = robotConfigs[i][0];
            Robot robot = new Robot(robotId, warehouse, itemsToAttempt);
            robotThreads[i] = new Thread(robot);
            robotThreads[i].start();
        }

        // Wait for all robot threads to complete
        for (Thread thread : robotThreads) {
            thread.join();
        }

        return "Final stock in warehouse: " + warehouse.getCurrentStock() + ", Capacity: " + warehouse.getCapacity();
    }
}

import java.util.LinkedList;
import java.util.Queue;

public class BoundedBuffer {
    private final Queue<Integer> buffer;
    private final int capacity;

    public BoundedBuffer(int capacity) {
        this.capacity = capacity;
        this.buffer = new LinkedList<>();
    }

    public void put(int item) throws InterruptedException {
        // Synchronize access to the buffer
        synchronized (this) {
            // While the buffer is full, the producer must wait.
            // Using a while loop is crucial to handle spurious wakeups
            // and re-check the condition after waking up.
            while (buffer.size() == capacity) {
                wait(); // Release the lock and wait for space to become available
            }
            // Add the item to the buffer
            buffer.offer(item);
            // Notify all waiting threads (especially consumers) that an item is available.
            // notifyAll() is safer than notify() in producer-consumer scenarios
            // to prevent potential deadlocks if the 'wrong' type of thread is notified.
            notifyAll();
        }
    }

    public int take() throws InterruptedException {
        // Synchronize access to the buffer
        synchronized (this) {
            // While the buffer is empty, the consumer must wait.
            // Using a while loop is crucial for the same reasons as in put().
            while (buffer.isEmpty()) {
                wait(); // Release the lock and wait for an item to become available
            }
            // Remove and return the item from the buffer
            int item = buffer.poll();
            // Notify all waiting threads (especially producers) that space is now available.
            notifyAll();
            return item;
        }
    }
}

