public class ServiceOrchestrator {

    // --- Provided Simulation Helper Methods (DO NOT MODIFY) ---
    private void configure(String configPath) throws ConfigurationException, IOException {
        System.out.println("Configuring with path: " + configPath);
        if ("invalid_value_config".equals(configPath)) {
            throw new InvalidConfigurationValueException("Configuration 'max_threads' has an invalid value: bad_value");
        }
        if ("config_io_error".equals(configPath)) {
            throw new IOException("Failed to read configuration file: config.txt");
        }
        // Simulate other successful configuration logic
    }

    private void processRecord(String record) {
        System.out.println("Processing record: " + record);
        if ("null_data".equals(record)) {
            throw new DataProcessingException("Encountered null data value for record.");
        }
        if ("divide_by_zero".equals(record)) {
            throw new ArithmeticException("Division by zero attempt during record processing.");
        }
        if ("npe_trigger".equals(record)) {
            String x = null;
            x.length(); // This will throw NPE
        }
        if ("invalid_format".equals(record)) {
            throw new DataProcessingException("Record format is invalid: " + record);
        }
        // Simulate other successful processing logic
    }

    private void writeResult(int successfulRecords, int failedRecords, String writeTrigger) throws ServiceOperationException, IOException {
        System.out.println(String.format("Writing result: Successful=%d, Failed=%d, Trigger=%s", successfulRecords, failedRecords, writeTrigger));
        if ("trigger_write_fail_op".equals(writeTrigger)) {
            throw new ServiceOperationException("Failed to write results due to operational error.");
        }
        if ("trigger_write_fail_io".equals(writeTrigger)) {
            throw new IOException("Disk full or I/O error during result write.");
        }
        // Simulate successful write
    }

    private void logError(String message, Throwable t) {
        System.err.println("ERROR: " + message + " - " + t.getClass().getSimpleName() + ": " + t.getMessage());
        if (t.getCause() != null) {
            System.err.println("       Caused by: " + t.getCause().getClass().getSimpleName() + ": " + t.getCause().getMessage());
        }
    }
    // --- End of Provided Simulation Helper Methods ---

    public ServiceRunReport runService(String configPath, List<String> dataRecords, String writeTrigger, String finallyTrigger) {
        ServiceRunReport report = new ServiceRunReport("UNKNOWN", 0, 0, "Service started.");
        int successfulRecords = 0;
        int failedRecords = 0;

        try {
            // Stage 1: Configuration
            configure(configPath);
            report.status = "CONFIGURED"; // Internal temporary status

            // Stage 2: Data Processing (only if config successful)
            for (String record : dataRecords) {
                try {
                    processRecord(record);
                    successfulRecords++;
                } catch (DataProcessingException e) {
                    logError("Data processing failed for record: " + record, e);
                    failedRecords++;
                } catch (RuntimeException e) {
                    DataProcessingException dpe = new DataProcessingException("Runtime error during data processing for record: " + record, e);
                    logError("Data processing failed for record: " + record, dpe);
                    failedRecords++;
                }
            }
            report.processedRecordsCount = successfulRecords;
            report.failedRecordsCount = failedRecords;

            // Stage 3: Result Writing (only if config successful)
            writeResult(successfulRecords, failedRecords, writeTrigger);
            report.status = (failedRecords == 0) ? "SUCCESS" : "PARTIAL_SUCCESS";
            report.finalMessage = (failedRecords == 0) ? "Service completed successfully." : "Service completed with partial success. Some records failed to process.";

        } catch (ConfigurationException | IOException e) { // Catches ConfigurationException and wrapped IOException
            Throwable cause = e; // Initially, the cause is 'e'
            if (e instanceof IOException) {
                // Wrap IOException in ConfigurationException first
                cause = new ConfigurationException("Underlying I/O error during configuration", e);
            }
            ServiceInitializationException sie = new ServiceInitializationException("Configuration error during service startup.", cause);
            logError("Service initialization failed", sie);
            report.status = "INITIALIZATION_FAILED";
            report.finalMessage = "Service initialization failed.";
            report.setRootCause(sie);
            return report; // Exit early as initialization failed

        } catch (ServiceOperationException | IOException e) { // Catches ServiceOperationException and wrapped IOException during writeResult
            Throwable cause = e;
            if (e instanceof IOException) {
                // Wrap IOException in ServiceOperationException first
                cause = new ServiceOperationException("Underlying I/O error during result writing", e);
            }
            // If processing was successful but write failed, it's a partial success.
            // If it was already partial due to record failures, this just adds to the root cause for reporting
            if (report.status.equals("CONFIGURED") || report.status.equals("PARTIAL_SUCCESS")) {
                report.status = "PARTIAL_SUCCESS";
                report.finalMessage = "Service completed with partial success. Failed to write results.";
                report.setRootCause(cause);
            } else { // Should not happen in this flow if initialization failed earlier
                 logError("Unexpected service operation error after initialization", cause);
                 report.status = "CRITICAL_FAILURE";
                 report.finalMessage = "Unexpected critical operational failure.";
                 report.setRootCause(cause);
            }

        } finally {
            // Preserve current exception for finally block logic
            Throwable currentException = null;
            // We need to capture the exception that might be pending before finally runs
            // However, a direct 'catch' cannot rethrow the original while still allowing finally to override.
            // The problem statement implies that if an exception happens in finally, it *replaces* any pending exception.

            try {
                System.out.println("Service finalization block executing.");
                if ("finally_runtime_error".equals(finallyTrigger)) {
                    throw new RuntimeException("Error during final service cleanup.");
                }
            } catch (RuntimeException e) {
                // An exception occurred within the finally block
                currentException = e;
                report.status = "CRITICAL_FAILURE_IN_FINALLY";
                report.finalMessage = "A critical error occurred in the service's finalization block.";
                report.setRootCause(currentException);
                logError("Critical error in finally block", currentException);
                // Rethrow the exception from finally, it will override any pending exception
                throw e;
            } finally {
                // This nested finally is just to ensure the report fields are set even if an exception occurs above
                // However, due to the 'throw e' above, this 'report' object might not be returned, so ensure it's set before re-throw.
                // The outer 'return report' will not be reached if an exception is thrown from the outer finally.
                // The challenge is to make sure the report is accurate *before* the finally exception propagates.
                // The simplest way to handle this for the problem's requirements is to set the report details *inside* the catch block of the finally. 
            }
        }

        // Default final message if everything was smooth and no specific status set by catches
        if ("UNKNOWN".equals(report.status) || "CONFIGURED".equals(report.status)) {
             report.status = (failedRecords == 0) ? "SUCCESS" : "PARTIAL_SUCCESS";
             report.finalMessage = (failedRecords == 0) ? "Service completed successfully." : "Service completed with partial success. Some records failed to process.";
        }

        return report;
    }
}

