// --- Application Entry Point ---
@SpringBootApplication
@EnableAsync
public class TaskOrchestrationApplication {

    public static void main(String[] args) {
        SpringApplication.run(TaskOrchestrationApplication.class, args);
    }

    // Define a custom Executor for @Async tasks to ensure proper thread management
    @Bean(name = "taskExecutor")
    public Executor taskExecutor() {
        ThreadPoolTaskExecutor executor = new ThreadPoolTaskExecutor();
        executor.setCorePoolSize(5);
        executor.setMaxPoolSize(10);
        executor.setQueueCapacity(25);
        executor.setThreadNamePrefix("AsyncTask-");
        executor.initialize();
        return executor;
    }
}

// --- DTOs ---
class InitiateTaskRequest {
