@JsonInclude(JsonInclude.Include.NON_NULL) // Only include non-null fields in JSON output
class TaskStatusResponse {
    private UUID taskId;
    private TaskState.Status status;
    private String result;
    private String error;

    public TaskStatusResponse(UUID taskId, TaskState.Status status) {
        this.taskId = taskId;
        this.status = status;
    }

    public TaskStatusResponse(UUID taskId, TaskState.Status status, String result, String error) {
        this.taskId = taskId;
        this.status = status;
        this.result = result;
        this.error = error;
    }

    // Getters and Setters (omitted for brevity in explanation, but required for JSON serialization)
    public UUID getTaskId() { return taskId; }
    public TaskState.Status getStatus() { return status; }
    public String getResult() { return result; }
    public String getError() { return error; }
    public void setTaskId(UUID taskId) { this.taskId = taskId; }
    public void setStatus(TaskState.Status status) { this.status = status; }
    public void setResult(String result) { this.result = result; }
    public void setError(String error) { this.error = error; }
}

// --- Task State Model ---
class TaskState {
    enum Status { PENDING, RUNNING, COMPLETED, FAILED }

    private UUID id;
    private String initialPayload;
    private volatile Status status;
    private volatile String result;
    private volatile String errorMessage;

    public TaskState(UUID id, String initialPayload) {
        this.id = id;
        this.initialPayload = initialPayload;
        this.status = Status.PENDING;
    }

    // Getters (omitted setters as state changes are managed internally by the service logic)
    public UUID getId() { return id; }
    public String getInitialPayload() { return initialPayload; }
    public Status getStatus() { return status; }
    public String getResult() { return result; }
    public String getErrorMessage() { return errorMessage; }

    // Synchronized setters to ensure thread-safe updates to task state fields
    public synchronized void setStatus(Status status) { this.status = status; }
    public synchronized void setResult(String result) { this.result = result; }
    public synchronized void setErrorMessage(String errorMessage) { this.errorMessage = errorMessage; }
}

// --- Service Layer ---
@Service
class TaskService {

    // Using ConcurrentHashMap for thread-safe in-memory storage of tasks
    private final Map<UUID, TaskState> tasks = new ConcurrentHashMap<>();
    private final TaskProcessorService taskProcessorService;

    public TaskService(TaskProcessorService taskProcessorService) {
        this.taskProcessorService = taskProcessorService;
    }

    public TaskState initiateTask(String payload) {
        UUID taskId = UUID.randomUUID();
        TaskState newTask = new TaskState(taskId, payload);
        tasks.put(taskId, newTask);

        // Start the asynchronous processing immediately
        taskProcessorService.processTask(newTask);

        return newTask;
    }

    public TaskState getTask(UUID taskId) {
        return tasks.get(taskId);
    }
}

@Service
class TaskProcessorService {

    // This method will be executed asynchronously using the 'taskExecutor' defined in TaskOrchestrationApplication
    @Async("taskExecutor")
    public CompletableFuture<Void> processTask(TaskState task) {
        task.setStatus(TaskState.Status.RUNNING);
        System.out.println(String.format("[%s] Task %s started processing with payload: %s", Thread.currentThread().getName(), task.getId(), task.getInitialPayload()));

        try {
            // Simulate long-running work
            TimeUnit.SECONDS.sleep(ThreadLocalRandom.current().nextInt(3, 9)); // Random duration 3-8 seconds

            // Simulate random failure
            if (ThreadLocalRandom.current().nextDouble() < 0.25) { // 25% chance of failure
                throw new RuntimeException("Simulated processing failure");
            }

            String processedResult = "Processed: " + task.getInitialPayload();
            task.setResult(processedResult);
            task.setStatus(TaskState.Status.COMPLETED);
            System.out.println(String.format("[%s] Task %s completed successfully. Result: %s", Thread.currentThread().getName(), task.getId(), processedResult));

        } catch (InterruptedException e) {
            Thread.currentThread().interrupt(); // Restore interrupt status
            task.setErrorMessage("Task interrupted: " + e.getMessage());
            task.setStatus(TaskState.Status.FAILED);
            System.err.println(String.format("[%s] Task %s failed (interrupted).", Thread.currentThread().getName(), task.getId()));
        } catch (Exception e) {
            // Generic error handling for simulated failures
            task.setErrorMessage("Simulated processing failure for " + task.getInitialPayload());
            task.setStatus(TaskState.Status.FAILED);
            System.err.println(String.format("[%s] Task %s failed with error: %s", Thread.currentThread().getName(), task.getId(), e.getMessage()));
        }
        return CompletableFuture.completedFuture(null);
    }
}

// --- Controller Layer ---
@RestController
@RequestMapping("/api/tasks")
public class TaskController {

    private final TaskService taskService;

    public TaskController(TaskService taskService) {
        this.taskService = taskService;
    }

    @PostMapping("/initiate")
    public ResponseEntity<TaskStatusResponse> initiateTask(@RequestBody InitiateTaskRequest request) {
        if (request == null || request.getPayload() == null || request.getPayload().trim().isEmpty()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Payload cannot be empty");
        }

        TaskState newTask = taskService.initiateTask(request.getPayload());

        HttpHeaders headers = new HttpHeaders();
        headers.add(HttpHeaders.LOCATION, "/api/tasks/" + newTask.getId());

        TaskStatusResponse response = new TaskStatusResponse(newTask.getId(), newTask.getStatus());

        return new ResponseEntity<>(response, headers, HttpStatus.ACCEPTED);
    }

    @GetMapping("/{taskId}")
    public ResponseEntity<TaskStatusResponse> getTaskStatus(@PathVariable UUID taskId) {
        TaskState task = taskService.getTask(taskId);

        if (task == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Task not found for ID: " + taskId);
        }

        TaskStatusResponse response = new TaskStatusResponse(
            task.getId(),
            task.getStatus(),
            task.getResult(),
            task.getErrorMessage()
        );

        return ResponseEntity.ok(response);
    }
}
