import collections

class Solution:
    def simplifyPath(self, path: str) -> str:
        # Use a deque as a stack for O(1) appends and pops
        stack = collections.deque()

        # Split the path by '/' to get individual components
        # For '/home//foo/', this might yield ['', 'home', '', 'foo', '']
        components = path.split('/')

        for comp in components:
            if comp == "" or comp == ".":
                # Ignore empty strings (from multiple slashes) and '.' (current directory)
                continue
            elif comp == "..":
                # If '..', pop from stack if not empty (go up one level)
                if stack:
                    stack.pop()
            else:
                # Regular directory name, push onto stack
                stack.append(comp)

        # Construct the result path
        # If the stack is empty, it means we are at the root directory
        if not stack:
            return "/"
        else:
            # Join the elements in the stack with '/' and prepend a '/' to make it absolute
            return "/" + "/".join(stack)

class DynamicTaskQueue:
    def __init__(self):
        # We use a Python list as the underlying data structure for the queue.
        # The front of the queue is at index 0, and the back is at the end of the list.
        self._queue = []

    def enqueue(self, task_id):
        # Adding to the back of the queue corresponds to appending to the list.
        # Time complexity: O(1) on average for Python lists.
        self._queue.append(task_id)

    def dequeue(self):
        # Removing from the front of the queue corresponds to removing the first element.
        # This operation (list.pop(0)) is O(N) because all subsequent elements need to be shifted.
        if self.is_empty():
            return None
        return self._queue.pop(0)

    def peek(self):
        # Peeking at the front is accessing the first element.
        # Time complexity: O(1).
        if self.is_empty():
            return None
        return self._queue[0]

    def is_empty(self):
        # Checking if the queue is empty is checking if the list is empty.
        # Time complexity: O(1).
        return len(self._queue) == 0

    def size(self):
        # The size of the queue is the length of the list.
        # Time complexity: O(1).
        return len(self._queue)

    def insert_at_position(self, task_id, position):
        # This is the special operation. It inserts at a 0-indexed position.
        # If position is out of bounds (>= current size), it's treated as enqueue.
        # Python's list.insert() handles boundary conditions for 'position' naturally
        # by inserting at the end if 'position' is too large.
        # Time complexity: O(N) because elements from the insert point onwards need to be shifted.

        # Ensure position is within valid bounds or at the end.
        # Python's list.insert(index, item) will insert at the end if index >= len(list)
        # For example, [1,2,3].insert(5, 4) -> [1,2,3,4]
        self._queue.insert(position, task_id)

