def searchBST(root: TreeNode, val: int) -> bool:
    # Base case 1: If the root is None, the value cannot be found in an empty tree/subtree.
    if root is None:
        return False

    # Base case 2: If the current node's value is equal to the target value, we found it.
    if root.val == val:
        return True

    # Recursive step: If the target value is less than the current node's value,
    # it must be in the left subtree (if it exists) due to BST properties.
    elif val < root.val:
        return searchBST(root.left, val)

    # Recursive step: If the target value is greater than the current node's value,
    # it must be in the right subtree (if it exists) due to BST properties.
    else: # val > root.val
        return searchBST(root.right, val)

def search(nums: list[int], target: int) -> int:
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2  # Prevents potential overflow for very large left/right

        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:  # nums[mid] > target
            right = mid - 1

    return -1

class Solution {
public:
    int significantPairs(std::vector<int>& nums) {
        if (nums.empty()) {
            return 0;
        }
        return mergeSortAndCount(nums, 0, nums.size() - 1);
    }

private:
    int mergeSortAndCount(std::vector<int>& nums, int low, int high) {
        if (low >= high) {
            return 0;
        }

        int mid = low + (high - low) / 2;
        int count = mergeSortAndCount(nums, low, mid) + mergeSortAndCount(nums, mid + 1, high);

        // Count significant pairs across the two halves
        // The two halves nums[low...mid] and nums[mid+1...high] are already sorted from recursive calls.
        int j = mid + 1; // Pointer for the right half
        for (int i = low; i <= mid; ++i) { // Pointer for the left half
            // Find all elements in the right half (starting from mid+1) that satisfy the condition with nums[i]
            while (j <= high && (long long)nums[i] > 2LL * nums[j]) { // Use long long to prevent overflow
                j++;
            }
            // All elements from nums[mid+1] up to nums[j-1] form a significant pair with nums[i]
            count += (j - (mid + 1));
        }

        // Standard merge step to sort the array nums[low...high]
        // This is crucial for subsequent recursive calls and the counting logic to work correctly.
        std::vector<int> temp;
        int p1 = low;
        int p2 = mid + 1;
        while (p1 <= mid && p2 <= high) {
            if (nums[p1] <= nums[p2]) {
                temp.push_back(nums[p1++]);
            } else {
                temp.push_back(nums[p2++]);
            }
        }
        while (p1 <= mid) {
            temp.push_back(nums[p1++]);
        }
        while (p2 <= high) {
            temp.push_back(nums[p2++]);
        }

        for (int k = 0; k < temp.size(); ++k) {
            nums[low + k] = temp[k];
        }

        return count;
    }
};

class Solution {
    public List<List<Integer>> fourSum(int[] nums, int target) {
        List<List<Integer>> result = new ArrayList<>();
        if (nums == null || nums.length < 4) {
            return result;
        }

        Arrays.sort(nums);

        int n = nums.length;

        for (int i = 0; i < n - 3; i++) {
            // Skip duplicates for the first element 'a'
            if (i > 0 && nums[i] == nums[i - 1]) {
                continue;
            }

            // Optimization: If the smallest possible sum with nums[i] is already greater than target,
            // no need to continue with larger nums[i] in the inner loops.
            // Using long to prevent potential overflow before comparison.
            if ((long) nums[i] + nums[i+1] + nums[i+2] + nums[i+3] > target) {
                break;
            }
            // Optimization: If the largest possible sum with nums[i] is already smaller than target,
            // nums[i] is too small. Skip this nums[i] and try a larger one.
            if ((long) nums[i] + nums[n-1] + nums[n-2] + nums[n-3] < target) {
                continue;
            }

            for (int j = i + 1; j < n - 2; j++) {
                // Skip duplicates for the second element 'b'
                if (j > i + 1 && nums[j] == nums[j - 1]) {
                    continue;
                }

                // Optimization for j loop: same logic as for i
                if ((long) nums[i] + nums[j] + nums[j+1] + nums[j+2] > target) {
                    break;
                }
                if ((long) nums[i] + nums[j] + nums[n-1] + nums[n-2] < target) {
                    continue;
                }

                int left = j + 1; // Pointer for 'c'
                int right = n - 1; // Pointer for 'd'

                while (left < right) {
                    // Calculate current sum, using long to prevent overflow
                    long currentSum = (long) nums[i] + nums[j] + nums[left] + nums[right];

                    if (currentSum == target) {
                        // Found a valid quadruplet
                        result.add(Arrays.asList(nums[i], nums[j], nums[left], nums[right]));

                        // Skip duplicates for the third element 'c'
                        while (left < right && nums[left] == nums[left + 1]) {
                            left++;
                        }
                        // Skip duplicates for the fourth element 'd'
                        while (left < right && nums[right] == nums[right - 1]) {
                            right--;
                        }

                        // Move pointers to find next unique pair
                        left++;
                        right--;
                    } else if (currentSum < target) {
                        // Sum is too small, need a larger 'c'
                        left++;
                    } else {
                        // Sum is too large, need a smaller 'd'
                        right--;
                    }
                }
            }
        }

        return result;
    }
}

