def normalize_sales_data(sales_data):
    customers = set()
    employees = set()
    products = set()
    orders = set()
    order_items = set()

    for row in sales_data:
        # Extract Customer data
        customers.add(
            (row["CustomerID"], row["CustomerName"], row["CustomerEmail"])
        )

        # Extract Employee data
        employees.add(
            (row["EmployeeID"], row["EmployeeName"])
        )

        # Extract Product data
        products.add(
            (row["ProductID"], row["ProductName"], row["ProductPrice"])
        )

        # Extract Order data
        orders.add(
            (row["OrderID"], row["OrderDate"], row["CustomerID"], row["EmployeeID"])
        )

        # Extract Order_Items data
        order_items.add(
            (row["OrderID"], row["ProductID"], row["Quantity"])
        )

    # Convert sets of tuples back to lists of dictionaries for output
    # Sorting is added for deterministic output for testing purposes.
    normalized_data = {
        "Customers": sorted([
            {"CustomerID": c[0], "CustomerName": c[1], "CustomerEmail": c[2]}
            for c in customers
        ], key=lambda x: x["CustomerID"]),
        "Employees": sorted([
            {"EmployeeID": e[0], "EmployeeName": e[1]}
            for e in employees
        ], key=lambda x: x["EmployeeID"]),
        "Products": sorted([
            {"ProductID": p[0], "ProductName": p[1], "ProductPrice": p[2]}
            for p in products
        ], key=lambda x: x["ProductID"]),
        "Orders": sorted([
            {"OrderID": o[0], "OrderDate": o[1], "CustomerID": o[2], "EmployeeID": o[3]}
            for o in orders
        ], key=lambda x: x["OrderID"]),
        "Order_Items": sorted([
            {"OrderID": oi[0], "ProductID": oi[1], "Quantity": oi[2]}
            for oi in order_items
        ], key=lambda x: (x["OrderID"], x["ProductID"])) # Composite key sort
    }

    return normalized_data

