import json

class DocumentManager:
    def __init__(self):
        self._documents = {}  # Stores {id: content}
        self._next_post_id = 1

    def _parse_id_from_path(self, path):
        parts = path.split('/')
        if len(parts) == 3 and parts[1] == 'documents' and parts[2].isdigit():
            return int(parts[2])
        return None

    def process_request(self, method, path, body):
        headers = {}
        status_code = 500 # Default to internal server error
        response_body = ""

        if path == '/documents':
            if method == 'POST':
                doc_id = self._next_post_id
                self._next_post_id += 1
                self._documents[doc_id] = body
                status_code = 201
                response_body = str(doc_id)
                headers['Location'] = f'/documents/{doc_id}'
            else:
                status_code = 405 # Method Not Allowed
                response_body = "Method Not Allowed for this path."
        elif path.startswith('/documents/'):
            doc_id = self._parse_id_from_path(path)
            if doc_id is None:
                status_code = 400 # Bad Request for malformed ID path
                response_body = "Invalid document ID in path."
                return status_code, response_body, headers

            if method == 'GET':
                if doc_id in self._documents:
                    status_code = 200
                    response_body = self._documents[doc_id]
                else:
                    status_code = 404
                    response_body = "Document Not Found"
            elif method == 'PUT':
                if doc_id in self._documents:
                    status_code = 200 # OK
                    self._documents[doc_id] = body
                    response_body = "" # As per problem statement, empty body for PUT success
                else:
                    status_code = 201 # Created
                    self._documents[doc_id] = body
                    headers['Location'] = f'/documents/{doc_id}'
                    response_body = "" # As per problem statement, empty body for PUT success
            elif method == 'PATCH':
                if doc_id not in self._documents:
                    status_code = 404
                    response_body = "Document Not Found"
                else:
                    try:
                        patch_data = json.loads(body)
                        if 'append' in patch_data and isinstance(patch_data['append'], str):
                            self._documents[doc_id] += patch_data['append']
                            status_code = 200
                            response_body = self._documents[doc_id]
                        else:
                            status_code = 400
                            response_body = "Invalid PATCH body: 'append' key missing or value not a string."
                    except json.JSONDecodeError:
                        status_code = 400
                        response_body = "Invalid PATCH body: Malformed JSON."
            elif method == 'DELETE':
                if doc_id in self._documents:
                    del self._documents[doc_id]
                    status_code = 204
                    response_body = ""
                else:
                    status_code = 404
                    response_body = "Document Not Found"
            else:
                status_code = 405 # Method Not Allowed
                response_body = "Method Not Allowed for this path."
        else:
            status_code = 404 # Not Found for other paths
            response_body = "Resource Not Found"

        return status_code, response_body, headers

def solve_document_management(requests):
    manager = DocumentManager()
    responses = []
    for method, path, body in requests:
        status_code, response_body, headers = manager.process_request(method, path, body)
        responses.append([status_code, response_body, headers]) # Use list for JSON output
    return responses

def getRestStatusCode(action, isSuccess, isNotFound):
    # First, handle 'Not Found' for unsuccessful operations that target a missing resource.
    # This takes precedence over general bad requests if the resource itself is the issue.
    if not isSuccess and isNotFound and (action == 'read' or action == 'update' or action == 'delete'):
        return 404  # Not Found

    # Next, handle successful operations
    if isSuccess:
        if action == 'create':
            return 201  # Created: Resource successfully created.
        elif action == 'read' or action == 'update':
            return 200  # OK: Operation successful, typically returning a representation.
        elif action == 'delete':
            return 204  # No Content: Operation successful, but no content to return.

    # Finally, handle all other unsuccessful operations as Bad Request.
    # This covers cases like invalid input for create/update, or other client errors where 
    # the resource wasn't found (if applicable) or the operation simply failed due to bad request.
    return 400  # Bad Request: General client error (e.g., invalid syntax, invalid parameters, invalid data).

