def needs_preflight(method: str, headers: dict) -> bool:
    # 1. Check HTTP method
    simple_methods = {"GET", "HEAD", "POST"}
    if method.upper() not in simple_methods:
        return True

    # 2. Check headers
    safelisted_general_headers = {
        "accept",
        "accept-language",
        "content-language"
    }

    safelisted_content_type_values = {
        "application/x-www-form-urlencoded",
        "multipart/form-data",
        "text/plain"
    }

    for header_name, header_value in headers.items():
        normalized_header_name = header_name.lower()

        if normalized_header_name == "content-type":
            # For Content-Type, we need to check its value. 
            # Ignore charset for comparison as per problem statement.
            content_type_base = header_value.split(';')[0].strip().lower()
            if content_type_base not in safelisted_content_type_values:
                return True # Non-safelisted Content-Type value
        elif normalized_header_name not in safelisted_general_headers:
            return True # Custom or non-safelisted header (not Content-Type)

    return False # All conditions for a simple request are met

class SimpleRateLimiter:
    def __init__(self, max_requests):
        self.available_requests = max_requests

    def canMakeRequest(self):
        if self.available_requests > 0:
            self.available_requests -= 1
            return True
        else:
            return False

def simulateRateLimiter(initial_max_limit, operations):
    limiter = SimpleRateLimiter(initial_max_limit)
    results = []
    for op in operations:
        if op == "call":
            results.append(limiter.canMakeRequest())
    return results

