import json

def simulate_git(commands):
    output = []
    repo_initialized = False
    files_on_disk = set()
    staged_files = set()
    # committed_files_at_head represents all files that have ever been committed
    # This set is used to determine which files are 'tracked' vs 'untracked'.
    committed_files_at_head = set() 
    commits = [] # List of {'id': N, 'message': 'msg'}
    next_commit_id = 1

    for command_str in commands:
        parts = command_str.split(' ', 1)
        cmd = parts[0]

        if cmd == "init":
            repo_initialized = True
            files_on_disk.clear() # Resetting state for a fresh init
            staged_files.clear()
            committed_files_at_head.clear()
            commits.clear()
            next_commit_id = 1
            output.append("Initialized empty Git repository.")

        elif cmd == "touch":
            if not repo_initialized:
                continue # For this simulation, assume files are only relevant in an initialized repo.
            filename = parts[1]
            files_on_disk.add(filename)

        elif cmd == "add":
            if not repo_initialized:
                continue # Problem assumes valid commands, so this case implies init was called.
            filename = parts[1]
            if filename in files_on_disk: # Only add if the file actually exists on disk
                staged_files.add(filename)

        elif cmd == "commit":
            message = parts[1]
            if not repo_initialized:
                continue # Problem assumes valid commands.
            if not staged_files:
                output.append("Nothing to commit.")
                continue

            # Create a new commit
            commits.append({"id": next_commit_id, "message": message})
            next_commit_id += 1

            # Add all currently staged files to the set of all historically committed files.
            # This ensures that once a file is committed, it's considered 'tracked'.
            committed_files_at_head.update(staged_files) 

            # Clear staged files after commit
            staged_files.clear()

        elif cmd == "status":
            if not repo_initialized:
                output.append("fatal: not a git repository (or any of the parent directories): .git")
                continue

            if not commits:
                output.append("No commits yet.")

            # Staged files
            if staged_files:
                output.append("Staged files: " + ", ".join(sorted(list(staged_files))))
            else:
                output.append("No staged files.")

            # Untracked files
            # Files on disk that are NOT part of the committed history AND NOT currently staged
            untracked = files_on_disk - committed_files_at_head - staged_files
            if untracked:
                output.append("Untracked files: " + ", ".join(sorted(list(untracked))))
            else:
                output.append("No untracked files.")

            # Repository clean? Only if there's at least one commit and nothing staged/untracked
            if not staged_files and not untracked and commits:
                output.append("Repository clean.")

        elif cmd == "log":
            if not repo_initialized:
                output.append("fatal: not a git repository (or any of the parent directories): .git")
                continue

            if not commits:
                output.append("No commits yet.")
            else:
                # Display most recent commit first
                for commit in reversed(commits):
                    output.append(f"commit {commit['id']}\n    {commit['message']}")

    return output

import collections

class Commit:
    def __init__(self, commit_id, message, parents=None):
        self.id = commit_id
        self.message = message
        self.parents = parents if parents is not None else []

    def __repr__(self):
        return self.id

class Repository:
    def __init__(self):
        self.branches = {}
        self.all_commits = {}
        self.head_branch_name = "main"
        self.next_commit_id_num = 0

        # Initial commit C0
        initial_commit = self._create_commit("Initial commit", [])
        self.branches["main"] = initial_commit
        self.all_commits[initial_commit.id] = initial_commit

    def _get_next_commit_id(self):
        commit_id = f"C{self.next_commit_id_num}"
        self.next_commit_id_num += 1
        return commit_id

    def _create_commit(self, message, parents_commits):
        commit_id = self._get_next_commit_id()
        new_commit = Commit(commit_id, message, parents_commits)
        self.all_commits[commit_id] = new_commit
        return new_commit

    def branch(self, new_branch_name, source_branch_name):
        if source_branch_name not in self.branches:
            raise ValueError(f"Source branch '{source_branch_name}' does not exist.")
        if new_branch_name in self.branches:
            raise ValueError(f"Branch '{new_branch_name}' already exists.")

        self.branches[new_branch_name] = self.branches[source_branch_name]

    def checkout(self, branch_name):
        if branch_name not in self.branches:
            raise ValueError(f"Branch '{branch_name}' does not exist.")
        self.head_branch_name = branch_name

    def commit(self, message):
        current_head_commit = self.branches[self.head_branch_name]
        new_commit = self._create_commit(message, [current_head_commit])
        self.branches[self.head_branch_name] = new_commit
        return new_commit

    def _is_ancestor(self, possible_ancestor, commit):
        # BFS to check if possible_ancestor is an ancestor of commit
        q = collections.deque([commit])
        visited = {commit.id}
        while q:
            current = q.popleft()
            if current.id == possible_ancestor.id:
                return True
            for parent in current.parents:
                if parent.id not in visited:
                    visited.add(parent.id)
                    q.append(parent)
        return False

    def merge(self, source_branch_name, target_branch_name):
        if source_branch_name not in self.branches:
            raise ValueError(f"Source branch '{source_branch_name}' does not exist.")
        if target_branch_name not in self.branches:
            raise ValueError(f"Target branch '{target_branch_name}' does not exist.")

        source_head = self.branches[source_branch_name]
        target_head = self.branches[target_branch_name]

        if source_head.id == target_head.id:
            # Already up-to-date
            return

        # Check for fast-forward
        if self._is_ancestor(target_head, source_head):
            self.branches[target_branch_name] = source_head
            if self.head_branch_name == target_branch_name:
                self.head_branch_name = target_branch_name # Update HEAD if needed
            return

        # Otherwise, a 3-way merge commit is created
        merge_commit = self._create_commit(
            f"Merge branch '{source_branch_name}' into '{target_branch_name}'",
            [target_head, source_head] # First parent is target_head, second is source_head
        )
        self.branches[target_branch_name] = merge_commit
        if self.head_branch_name == target_branch_name:
            self.head_branch_name = target_branch_name # Update HEAD if needed

    def get_history(self, branch_name):
        if branch_name not in self.branches:
            raise ValueError(f"Branch '{branch_name}' does not exist.")

        head_commit = self.branches[branch_name]

        # Use DFS post-order traversal to get topological sort (oldest to newest),
        # then reverse for newest to oldest.
        temp_history = []
        visited = set()

        def dfs_post_order(commit):
            if commit is None or commit.id in visited:
                return
            visited.add(commit.id)

            # Prioritize first parent's history path for deterministic output
            for parent in commit.parents:
                dfs_post_order(parent)

            temp_history.append(commit.id)

        dfs_post_order(head_commit)
        return list(reversed(temp_history))

def simulate_git_workflow(commands):
    repo = Repository()

    for command_str in commands:
        parts = command_str.split()
        cmd = parts[0]

        if cmd == "BRANCH":
            new_branch = parts[1]
            source_branch = parts[3] # FROM <source_branch>
            repo.branch(new_branch, source_branch)
        elif cmd == "CHECKOUT":
            branch_name = parts[1]
            repo.checkout(branch_name)
        elif cmd == "COMMIT":
            message = parts[1]
            repo.commit(message)
        elif cmd == "MERGE":
            source_branch = parts[1]
            target_branch = parts[3] # INTO <target_branch>
            repo.merge(source_branch, target_branch)
        else:
            raise ValueError(f"Unknown command: {command_str}")

    return repo.get_history("main")

def identify_ci_cd_stage(action_keyword):
    action_map = {
        'commit': 'Source Control',
        'push': 'Source Control',
        'build': 'Build',
        'compile': 'Build',
        'test': 'Test',
        'qa': 'Test',
        'deploy': 'Deployment',
        'release': 'Deployment'
    }

    # Convert input to lowercase to handle case insensitivity
    return action_map.get(action_keyword.lower(), 'Unknown Stage')

