class Solution:
    def countPairsWithBitwiseAndZero(self, nums: list[int]) -> int:
        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if (nums[i] & nums[j]) == 0:
                    count += 1
        return count

import collections

class Solution:
    def numWaysToJump(self, nums: list[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0
        if n == 1:
            return 1

        MOD = 10**9 + 7

        # dp[i] will store the number of ways to reach index i
        dp = [0] * n
        dp[0] = 1  # There is one way to start at index 0

        for i in range(n):
            # If dp[i] is 0, it means index i is unreachable, so no jumps can be made from it.
            if dp[i] == 0:
                continue

            # Option 1: Normal jump to i+1
            if i + 1 < n:
                dp[i+1] = (dp[i+1] + dp[i]) % MOD

            # Option 2: Extended jump to i+2
            # This jump is only possible if nums[i+1] > nums[i]
            if i + 2 < n:
                # Check the condition for extended jump: nums[i+1] must be strictly greater than nums[i]
                if nums[i+1] > nums[i]:
                    dp[i+2] = (dp[i+2] + dp[i]) % MOD

        return dp[n-1]

def mostFrequentEven(nums):
    freq_map = {}
    for num in nums:
        # Check if the number is even using bitwise AND
        if (num & 1) == 0:
            freq_map[num] = freq_map.get(num, 0) + 1

    max_freq = -1
    result = -1

    # Iterate through the frequency map to find the most frequent even number
    # and handle tie-breaking for the smallest number.
    for num, count in sorted(freq_map.items()): # Sorting ensures smaller number is considered first for same frequency
        if count > max_freq:
            max_freq = count
            result = num
        elif count == max_freq:
            result = min(result, num) # This line handles the tie-breaking if not sorted
                                      # However, iterating sorted(items()) already helps simplify tie-breaking logic.

    # Re-evaluate the tie-breaking logic carefully. If we sort by number, and then by frequency, it's easier.
    # A simpler way without explicit sort: iterate through map, keep track of max_freq and smallest number with that freq.

    if not freq_map:
        return -1

    # Let's re-implement the finding loop to be clearer about tie-breaking without full sorting initially.
    max_freq = -1
    result = -1
    for num, count in freq_map.items():
        if count > max_freq:
            max_freq = count
            result = num
        elif count == max_freq:
            # If current number has same max_freq, choose the smaller one
            result = min(result, num)

    return result

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def sum_vertical_column(root: TreeNode, k: int) -> int:
    column_sum = 0

    def dfs(node, col):
        nonlocal column_sum
        if not node:
            return

        # If current node is in the target column, add its value
        if col == k:
            column_sum += node.val

        # Recurse for children, adjusting column index
        dfs(node.left, col - 1)
        dfs(node.right, col + 1)

    # Start DFS from the root at column 0
    dfs(root, 0)
    return column_sum

import collections

# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def verticalOrderTraversalWithSum(root: TreeNode) -> list[list[int]]:
    if not root:
        return []

    # Map: col -> (row -> sum_of_values_at_this_pos)
    # Using a regular dict for columns, and defaultdict for rows to handle sums easily.
    col_to_row_sums = {}

    # Store nodes to visit: (node, col, row)
    queue = collections.deque([(root, 0, 0)])

    while queue:
        node, col, row = queue.popleft()

        if col not in col_to_row_sums:
            col_to_row_sums[col] = collections.defaultdict(int)

        # Aggregate values at the same (col, row)
        col_to_row_sums[col][row] += node.val

        if node.left:
            queue.append((node.left, col - 1, row + 1))
        if node.right:
            queue.append((node.right, col + 1, row + 1))

    result = []
    # Iterate through columns in sorted order
    for col in sorted(col_to_row_sums.keys()):
        current_col_list = []
        # Get the map for the current column: row -> sum_of_values
        row_sums = col_to_row_sums[col]
        # Sort rows for the current column
        for row in sorted(row_sums.keys()):
            current_col_list.append(row_sums[row])
        result.append(current_col_list)

    return result

def uniquePaths(grid: list[list[int]]) -> int:
    m = len(grid)
    if m == 0:
        return 0
    n = len(grid[0])
    if n == 0:
        return 0

    memo = {}

    def find_paths(r: int, c: int) -> int:
        # If result for this cell is already computed, return it
        if (r, c) in memo:
            return memo[(r, c)]

        # Base case 1: If we reached the target (bottom-right corner)
        if r == m - 1 and c == n - 1:
            return 1

        # Base case 2: If we went out of bounds (past the grid)
        if r >= m or c >= n:
            return 0

        # Recursive step: Sum paths from moving down and moving right
        paths = find_paths(r + 1, c) + find_paths(r, c + 1)

        # Store the result in memoization table
        memo[(r, c)] = paths
        return paths

    # Start the path finding from the top-left corner (0, 0)
    return find_paths(0, 0)

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def solve(root: TreeNode) -> bool:
    if not root:
        return True # An empty tree has no leaf nodes, so all (zero) are covered.

    def dfs(node: TreeNode, parent_is_sentinel: bool) -> bool:
        if not node:
            return True

        is_node_sentinel = (
            (node.left is not None and node.right is None) or
            (node.left is None and node.right is not None)
        )

        is_leaf = (node.left is None and node.right is None)

        if is_leaf:
            # A leaf is covered if its parent is a sentinel.
            return parent_is_sentinel

        # For non-leaf nodes, recursively check if all leaves in its subtrees are covered.
        # The current node's sentinel status is passed to its children as their 'parent_is_sentinel' flag.
        left_covered = dfs(node.left, is_node_sentinel)
        right_covered = dfs(node.right, is_node_sentinel)

        return left_covered and right_covered

    # The root node has no parent, so its 'parent_is_sentinel' is False.
    return dfs(root, False)

def solve(s: str) -> int:
    n_pairs = len(s) // 2
    if n_pairs == 0:
        return 0

    pairs = []
    for i in range(n_pairs):
        pairs.append((s[2 * i], s[2 * i + 1]))

    # dp[i] stores the length of the longest non-decreasing subsequence ending at index i
    dp = [1] * n_pairs 

    max_len = 1 # At least one pair can always form a subsequence of length 1

    for i in range(1, n_pairs):
        for j in range(i):
            # Check if pairs[i] can follow pairs[j]
            # (p1_j, p2_j) to (p1_i, p2_i)
            if pairs[j][0] <= pairs[i][0] and pairs[j][1] <= pairs[i][1]:
                dp[i] = max(dp[i], 1 + dp[j])
        max_len = max(max_len, dp[i])

    # Minimum deletions = Total pairs - Maximum pairs kept
    return n_pairs - max_len

def minOperations(target: int) -> int:
    if target == 1:
        return 0

    operations = 0
    current = target

    # Work backwards from target to 1
    while current > 1:
        if current % 2 == 0:
            # If even, best to divide by 2 (reverse of multiply by 2)
            current //= 2
        else:
            # If odd, must subtract 1 to make it even (reverse of add 1)
            current -= 1
        operations += 1

    return operations

def longestLexicographicallySortedColumnSubsequence(strs: list[str]) -> int:
    if not strs:
        return 0

    N = len(strs)  # Number of strings (rows)
    M = len(strs[0]) if N > 0 else 0  # Length of each string (columns)

    if M == 0:
        return 0

    # dp[j] will store the length of the longest lexicographically sorted 
    # column subsequence ending at column j.
    dp = [1] * M

    max_len = 1

    for j in range(M):
        # Current column characters: (strs[0][j], strs[1][j], ..., strs[N-1][j])
        for p in range(j):
            # Previous column characters: (strs[0][p], strs[1][p], ..., strs[N-1][p])

            # Check if column p can precede column j
            can_precede = True
            for r in range(N):
                if strs[r][p] > strs[r][j]:
                    can_precede = False
                    break

            if can_precede:
                dp[j] = max(dp[j], 1 + dp[p])

        max_len = max(max_len, dp[j])

    return max_len

import collections

class Solution:
    def largestSubsetConnectedByCommonPrimeFactor(self, nums: list[int]) -> int:
        if not nums:
            return 0

        # Determine the maximum value in nums to set the sieve limit
        MAX_NUM_VAL = 0
        for num in nums:
            if num > MAX_NUM_VAL:
                MAX_NUM_VAL = num

        # Sieve of Eratosthenes to precompute primes up to MAX_NUM_VAL
        # We need at least 2 for sieve_limit if MAX_NUM_VAL is 0 or 1
        sieve_limit = max(2, MAX_NUM_VAL)
        is_prime = [True] * (sieve_limit + 1)
        if sieve_limit >= 0: is_prime[0] = False
        if sieve_limit >= 1: is_prime[1] = False

        primes = []
        for p in range(2, sieve_limit + 1):
            if is_prime[p]:
                primes.append(p)
                for multiple in range(p * p, sieve_limit + 1, p):
                    is_prime[multiple] = False

        prime_factor_counts = collections.defaultdict(int)
        max_subset_size = 0

        for num in nums:
            if num == 1:
                continue # 1 has no prime factors

            # Find distinct prime factors for current num efficiently using precomputed primes
            current_num_factors = set()
            temp_num = num
            for p in primes:
                if p * p > temp_num: 
                    break # Optimization: only check primes up to sqrt(temp_num)
                if temp_num % p == 0:
                    current_num_factors.add(p)
                    while temp_num % p == 0:
                        temp_num //= p
            if temp_num > 1: # If temp_num is still > 1, it means it's a prime factor itself
                current_num_factors.add(temp_num)

            # Update counts for each prime factor found
            for factor in current_num_factors:
                prime_factor_counts[factor] += 1
                max_subset_size = max(max_subset_size, prime_factor_counts[factor])

        # Handle cases where no common prime factors were found for multiple numbers.
        # If there were numbers > 1 in nums, the largest subset is at least 1 (any single number).
        # If all numbers were 1s or nums was empty, max_subset_size correctly remains 0.
        if max_subset_size == 0 and any(n > 1 for n in nums):
             return 1

        return max_subset_size

import collections

class UnionFind:
    def __init__(self):
        self.parent = {}
        self.size = {}

    def find(self, i):
        if i not in self.parent:
            self.parent[i] = i
            self.size[i] = 1
        if self.parent[i] == i:
            return i
        self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)
        if root_i != root_j:
            # Union by size heuristic
            if self.size[root_i] < self.size[root_j]:
                root_i, root_j = root_j, root_i
            self.parent[root_j] = root_i
            self.size[root_i] += self.size[root_j]
            return True
        return False

def get_prime_factors(n, spf):
    factors = set()
    temp_n = n
    while temp_n > 1:
        factor = spf[temp_n]
        factors.add(factor)
        while temp_n % factor == 0:
            temp_n //= factor
    return list(factors)

def largestComponentSize(nums: list[int]) -> int:
    if not nums:
        return 0
    if len(nums) == 1:
        return 1

    max_val = max(nums)

    # Sieve of Eratosthenes to precompute Smallest Prime Factor (SPF)
    # spf[i] stores the smallest prime factor of i
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i: # i is prime
            for multiple in range(i*i, max_val + 1, i):
                if spf[multiple] == multiple: # Only update if a smaller prime factor hasn't been found yet
                    spf[multiple] = i

    uf = UnionFind()

    # For each number, find its prime factors and union them in the UF structure.
    # This effectively groups all numbers that share common prime factors.
    for num in nums:
        prime_factors = get_prime_factors(num, spf)
        if not prime_factors:
            continue # Should not happen for num >= 2

        first_prime_factor = prime_factors[0]
        uf.find(first_prime_factor) # Ensure the first prime factor is in UF

        for i in range(1, len(prime_factors)): # Union all other prime factors with the first one
            uf.union(first_prime_factor, prime_factors[i])

    # Count how many original numbers belong to each component represented by a prime factor's root.
    component_counts = collections.defaultdict(int)
    max_component_size = 0

    for num in nums:
        prime_factors = get_prime_factors(num, spf)
        if not prime_factors: # Handle case if num is 1 or no prime factors found
            component_counts[num] += 1 # Treat as a component of size 1
            max_component_size = max(max_component_size, 1)
            continue

        # Find the root of any of its prime factors. This root represents the component.
        root = uf.find(prime_factors[0])
        component_counts[root] += 1
        max_component_size = max(max_component_size, component_counts[root])

    return max_component_size

def count_characters(s: str) -> dict[str, int]:
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1
    return char_counts

import re

def word_frequency_counter(text: str) -> dict:
    if not text:
        return {}

    # Convert the entire text to lowercase to handle case-insensitivity
    text = text.lower()

    # Use regex to find all sequences of word characters. This automatically handles punctuation.
    # '\b' is for word boundaries, '\w+' matches one or more word characters (alphanumeric + underscore)
    words = re.findall(r'\b\w+\b', text)

    # Initialize an empty dictionary to store word frequencies
    frequency_map = {}

    # Iterate through the extracted words and update their counts
    for word in words:
        frequency_map[word] = frequency_map.get(word, 0) + 1

    return frequency_map

problemStatement:
Given a list of integers, `nums`, write a function `count_frequencies` that returns a dictionary (or hash map) where each key is a unique integer from `nums` and its corresponding value is the number of times it appears in `nums`.

### Examples:

```
count_frequencies([1, 2, 2, 3, 1, 4]) == {1: 2, 2: 2, 3: 1, 4: 1}
count_frequencies([5, 5, 5]) == {5: 3}
count_frequencies([]) == {}
```

### Constraints:

*   The input list `nums` can be empty.
*   Elements in `nums` will be integers.

canonicalSolution:
def count_frequencies(nums):
    frequency_map = {}
    for num in nums:
        frequency_map[num] = frequency_map.get(num, 0) + 1
    return frequency_map

from collections import defaultdict

class DisjointSetUnion:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, i):
        if self.parent[i] == i:
            return i
        self.parent[i] = self.find(self.parent[i])
        return self.parent[i]

    def union(self, i, j):
        root_i = self.find(i)
        root_j = self.find(j)

        if root_i != root_j:
            if self.rank[root_i] < self.rank[root_j]:
                self.parent[root_i] = root_j
            elif self.rank[root_j] < self.rank[root_i]:
                self.parent[root_j] = root_i
            else:
                self.parent[root_j] = root_i
                self.rank[root_i] += 1
            return True
        return False

def get_char_counts(s):
    counts = defaultdict(int)
    for char in s:
        counts[char] += 1
    return counts

def are_k_anagrams(s1, s2, k):
    # Problem statement assumes same length for all words, 
    # but a check here is good for robustness if this function were standalone.
    # if len(s1) != len(s2):
    #     return False 

    counts1 = get_char_counts(s1)
    counts2 = get_char_counts(s2)

    diff_count = 0
    # Iterate over all characters present in either string's counts
    all_chars = set(counts1.keys()).union(counts2.keys())

    for char in all_chars:
        diff_count += abs(counts1[char] - counts2[char])

    # Each 'change' typically involves changing one character in s1 to match s2.
    # For example, if s1 has 'a' and s2 has 'b', abs(c1['a']-c2['a']) = 1, abs(c1['b']-c2['b']) = 1.
    # The total 'diff_count' is the sum of these absolute differences. 
    # To find the minimum number of changes, we divide by 2 because each character change 
    # accounts for two differences in the frequency map sum (one char's count decreases, another increases).
    return (diff_count // 2) <= k

def group_k_anagrams(words: list[str], k: int) -> list[list[str]]:
    n = len(words)
    if n == 0:
        return []

    dsu = DisjointSetUnion(n)

    # Compare each pair of words to determine k-anagram relationships
    for i in range(n):
        for j in range(i + 1, n):
            if are_k_anagrams(words[i], words[j], k):
                dsu.union(i, j)

    # Group words based on their representative (root) in the DSU structure
    groups = defaultdict(list)
    for i in range(n):
        root = dsu.find(i)
        groups[root].append(words[i])

    return list(groups.values())
